use moloch_replay::{engine::Engine,session::Session,Side};
use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{fs,path::PathBuf,sync::atomic::{AtomicU64,Ordering}};
const BASE:i64=1_792_054_800_000;
fn iso(t:i64)->String{chrono::DateTime::from_timestamp_millis(BASE+t).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn hash(v:&Value)->String{format!("{:x}",Sha256::digest(serde_json::to_vec(v).unwrap()))}
struct F{root:PathBuf,bank:Option<Session>,policy:Value,seed:Value}
impl Drop for F{fn drop(&mut self){self.bank.take();let _=fs::remove_dir_all(&self.root);}}
impl F{
 fn new(changes:Value)->Self{
  static N:AtomicU64=AtomicU64::new(0);let root=std::env::temp_dir().join(format!("profitable-depth-{}-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos(),N.fetch_add(1,Ordering::Relaxed)));fs::create_dir(&root).unwrap();
  let mut policy=json!({"initialCash":"10000.000000","maximumCommitted":"10000.000000","maximumMarketCost":"10000.000000","quantity":1000,"entriesEnabled":false,"inventoryExitMode":"fixedGain","inventoryExitDepthBps":5000,"inventoryMinimumGain":"0.005000","inventoryTakerAfterMs":0,"maximumInventoryAgeMs":60000,"inventoryAgeClock":"execution","entryStopAt":iso(120000)});
  for(k,v)in changes.as_object().unwrap(){policy[k]=v.clone();}
  let seed=json!({"runId":"depth-fixture","tournamentId":"cup","availableCash":"10000.000000","accountSnapshotHash":"a".repeat(64),"observedAt":iso(0)});
  let bank=Session::open_live(&root.join("bank"),&policy,&seed).unwrap();Self{root,bank:Some(bank),policy,seed}
 }
 fn b(&self)->&Session{self.bank.as_ref().unwrap()}
 fn put(&mut self,e:&Value)->Result<bool,Box<dyn std::error::Error>>{let n=self.b().last_source_sequence("fixture")+1;self.bank.as_mut().unwrap().accept("fixture",n,e)}
 fn event(&self,enabled:bool,at:i64)->Value{json!({"type":"ordinary_profitable_depth_mode_v1","source":"moloch_live_dispatcher","receivedAt":iso(at),"processedAt":iso(at),"bankScope":{"runId":"depth-fixture","bankManifestHash":self.b().manifest_hash(),"tournamentId":"cup"},"bankHead":self.b().durable_head(),"expectedReportSha256":hash(&self.b().engine().report().unwrap()),"expectedPolicySha256":hash(self.b().engine().policy()),"controlSha256":"b".repeat(64),"expectedPreviousModeSha256":self.b().engine().profitable_depth_mode_record().map_or(Value::Null,|r|r["sha256"].clone()),"enabled":enabled,"depthBps":5000})}
 fn mode(&mut self,enabled:bool,at:i64){let e=self.event(enabled,at);self.put(&e).unwrap();}
 fn adopt(&mut self,side:&str,n:u64){let cost=moloch_replay::money(690000*n as i128);self.put(&json!({"type":"actual_position_adoption","source":"official_sig_api_v1","authority":"human_moloch_inherited_management_20261015","complete":true,"receiptHash":"c".repeat(64),"tournamentId":"cup","requestStartedAt":iso(0),"receivedAt":iso(0),"processedAt":iso(0),"openingCost":cost,"effectiveMaximumMarkets":5,"positions":[{"exchangeId":"101","marketId":"101","quantity":if side=="NO"{-(n as i64)}else{n as i64},"lotPrincipal":cost,"reportedCostBasis":cost,"reportedMinusLotPrincipal":"0.000000","basisClassification":"exact","lots":[{"lotId":"901","quantity":n,"side":side,"entryPrice":"0.690000","openedAt":iso(-1000)}]}]})).unwrap();}
 fn book(&mut self,bids:Value,asks:Value,at:i64,invalid:bool){self.put(&json!({"type":"book","receivedAt":iso(at),"book":{"marketId":"101","exchangeId":"101","tournamentId":"cup","sequence":(at+1).to_string(),"sourceAt":iso(at),"requestStartedAt":iso(at),"receivedAt":iso(at),"invalid":invalid,"bids":bids,"asks":asks}})).unwrap();}
 fn yes(&mut self,at:i64){self.book(json!([{"price":"0.705000","quantity":1},{"price":"0.700000","quantity":999},{"price":"0.690000","quantity":9000}]),json!([{"price":"0.710000","quantity":1000}]),at,false);}
 fn exits(&self)->Vec<Value>{self.b().engine().order_records().into_iter().filter(|q|q["retired"]==false&&q["action"]=="sell"&&q["executionStyle"]=="inventoryAON").collect()}
 fn exclusions(&mut self,at:i64){let e=json!({"type":"ordinary_entry_exclusions_v1","source":"moloch_live_dispatcher","receivedAt":iso(at),"processedAt":iso(at),"bankScope":{"runId":"depth-fixture","bankManifestHash":self.b().manifest_hash(),"tournamentId":"cup"},"bankHead":self.b().durable_head(),"expectedReportSha256":hash(&self.b().engine().report().unwrap()),"managedExchangeIds":["101"],"approvedReviewSetSha256":"d".repeat(64),"controlSha256":"e".repeat(64),"expectedPreviousExclusionSha256":null});self.put(&e).unwrap();}
}
#[test]fn absent_mode_keeps_original_top_depth_zero_and_omits_report_and_policy_fields(){let mut f=F::new(json!({}));f.adopt("YES",1000);f.yes(1);assert!(f.exits().is_empty());assert!(!f.b().engine().profitable_depth_enabled());assert!(f.b().engine().report().unwrap().get("profitableDepthMode").is_none());assert!(f.b().engine().policy().get("profitableDepthMode").is_none());}
#[test]fn durable_install_does_not_replan_release_or_fill_and_future_book_uses_actual_marginal_price(){let mut f=F::new(json!({}));f.adopt("YES",1000);f.yes(1);let orders=f.b().engine().order_records();let before=f.b().engine().report().unwrap();let policy=f.b().engine().policy().clone();f.mode(true,2);assert_eq!(f.b().engine().order_records(),orders);assert_eq!(f.b().engine().policy(),&policy);for k in ["cash","ownedCost","reservedCash","realized","openingInventoryCost"]{assert_eq!(before[k],f.b().engine().report().unwrap()[k],"{k}");}f.yes(3);let q=&f.exits()[0];assert_eq!(q["quantity"],500);assert_eq!(q["price"],"0.700000");assert_eq!(q["side"],"YES");assert!(f.b().engine().fills().is_empty());assert_eq!(f.b().engine().wallet.quantity("101",Side::Yes),1000);}
#[test]fn no_side_uses_complement_of_each_actual_ask_level_not_best_price_for_deeper_quantity(){let mut f=F::new(json!({}));f.adopt("NO",1000);f.mode(true,0);f.book(json!([{"price":"0.290000","quantity":1000}]),json!([{"price":"0.295000","quantity":1},{"price":"0.300000","quantity":999},{"price":"0.310000","quantity":9000}]),1,false);let q=&f.exits()[0];assert_eq!(q["side"],"NO");assert_eq!(q["quantity"],500);assert_eq!(q["price"],"0.700000");}
#[test]fn fees_exclude_deeper_unprofitable_levels_instead_of_averaging_them(){let mut f=F::new(json!({"feePerShare":"0.003000"}));f.adopt("YES",1000);f.mode(true,0);f.yes(1);assert!(f.exits().is_empty());}
#[test]fn owned_cap_selects_top_price_when_all_requested_shares_fit_top_level(){let mut f=F::new(json!({}));f.adopt("YES",1);f.mode(true,0);f.yes(1);let q=&f.exits()[0];assert_eq!(q["quantity"],1);assert_eq!(q["price"],"0.705000");}
#[test]fn managed_forecast_scope_retains_original_exit_sizing(){let mut f=F::new(json!({}));f.adopt("YES",1000);f.exclusions(0);f.mode(true,0);f.yes(1);assert!(f.exits().is_empty());}
#[test]fn invalid_book_cannot_supply_cumulative_depth(){let mut f=F::new(json!({}));f.adopt("YES",1000);f.mode(true,0);f.book(json!([{"price":"0.700000","quantity":1000}]),json!([{"price":"0.710000","quantity":1000}]),1,true);assert!(f.exits().is_empty());}
#[test]fn existing_sell_pledge_does_not_allow_a_second_full_position_exit(){let mut f=F::new(json!({}));f.adopt("YES",1000);f.mode(true,0);f.yes(1);f.yes(3001);let total:u64=f.exits().iter().map(|q|q["quantity"].as_u64().unwrap()-q["filled"].as_u64().unwrap()).sum();assert_eq!(total,500);assert!(total<=f.b().engine().wallet.quantity("101",Side::Yes));}
#[test]fn ordinary_actual_ack_and_fill_keep_fifo_cost_inherited_attribution_and_exact_cash(){let mut f=F::new(json!({}));f.adopt("YES",1000);f.mode(true,0);f.yes(1);let q=f.exits()[0].clone();let before=f.b().engine().wallet.cash;
 let base=json!({"source":"official_sig_api_v1","receiptHash":"f".repeat(64),"orderId":q["id"],"actualOrderId":"902","marketId":"101","exchangeId":"101","side":"YES","action":"sell","quantity":500,"price":"0.700000","receivedAt":iso(3002)});let mut ack=base.clone();ack["type"]=json!("actual_order_ack");f.put(&ack).unwrap();assert!(f.b().engine().fills().is_empty());assert_eq!(f.b().engine().wallet.cash,before);
 let mut fill=base;fill["type"]=json!("actual_fill");fill["fillId"]=json!("903");fill["fee"]=json!("0.000000");fill["executedAt"]=json!(iso(3002));f.put(&fill).unwrap();assert_eq!(f.b().engine().wallet.cash-before,350_000_000);assert_eq!(f.b().engine().wallet.quantity("101",Side::Yes),500);assert_eq!(f.b().engine().report().unwrap()["inheritedRealizedGross"],"5.000000");assert_eq!(f.b().engine().report().unwrap()["newTradingRealized"],"0.000000");assert_eq!(f.b().engine().fills().len(),1);
}
#[test]fn actual_new_lot_maximum_age_loss_exit_retains_original_top_depth_fraction_and_price(){
 for enabled in [false,true]{let mut f=F::new(json!({"entriesEnabled":true}));f.book(json!([{"price":"0.690000","quantity":2000}]),json!([{"price":"0.710000","quantity":2000}]),0,false);let q=f.b().engine().order_records().into_iter().find(|q|q["action"]=="buy"&&q["side"]=="YES").unwrap();
 let mut e=json!({"type":"actual_order_ack","source":"official_sig_api_v1","receiptHash":"a".repeat(64),"orderId":q["id"],"actualOrderId":"904","marketId":"101","exchangeId":"101","side":"YES","action":"buy","quantity":q["quantity"],"price":q["price"],"receivedAt":iso(3000)});f.put(&e).unwrap();e["type"]=json!("actual_fill");e["fillId"]=json!("905");e["fee"]=json!("0.000000");e["executedAt"]=json!(iso(3000));f.put(&e).unwrap();
 for q in f.b().engine().order_records().into_iter().filter(|q|q["retired"]==false){f.put(&json!({"type":"unsubmitted_intent_retired","source":"moloch_live_dispatcher","orderId":q["id"],"receiptHash":"d".repeat(64),"confirmedNetworkAttempts":0,"deferPlanningForPackage":true,"receivedAt":iso(3001)})).unwrap();}
 if enabled{f.mode(true,3002)}f.book(json!([{"price":"0.600000","quantity":10},{"price":"0.595000","quantity":9990}]),json!([{"price":"0.610000","quantity":1000}]),64000,false);let q=&f.exits()[0];assert_eq!(q["quantity"],5);assert_eq!(q["price"],"0.600000");assert_eq!(q["inventoryExitReason"],"maximumAge");
 }
}
#[test]fn mode_prefix_scope_previous_policy_and_fraction_are_atomic_guards(){for case in ["head","report","run","manifest","tournament","previous","source","control","policy","fraction","future","enabled"]{let mut f=F::new(json!({}));let mut e=f.event(true,0);match case{"head"=>e["bankHead"]["sequence"]=json!(99),"report"=>e["expectedReportSha256"]=json!("e".repeat(64)),"run"=>e["bankScope"]["runId"]=json!("other"),"manifest"=>e["bankScope"]["bankManifestHash"]=json!("e".repeat(64)),"tournament"=>e["bankScope"]["tournamentId"]=json!("other"),"previous"=>e["expectedPreviousModeSha256"]=json!("e".repeat(64)),"source"=>e["source"]=json!("official_sig_api_v1"),"control"=>e["controlSha256"]=json!("bad"),"policy"=>e["expectedPolicySha256"]=json!("e".repeat(64)),"fraction"=>e["depthBps"]=json!(10000),"future"=>e["receivedAt"]=json!(iso(1)),_=>e["enabled"]=json!("true")};let head=f.b().durable_head();let report=f.b().engine().report().unwrap();assert!(f.put(&e).is_err(),"{case}");assert_eq!(f.b().durable_head(),head);assert_eq!(f.b().engine().report().unwrap(),report);}}
#[test]fn original_depth_policy_must_be_fifty_percent(){let mut f=F::new(json!({"inventoryExitDepthBps":10000}));let e=f.event(true,0);assert!(f.put(&e).is_err());}
#[test]fn paper_and_standalone_seed_cannot_install_or_drop_live_mode(){let mut f=F::new(json!({}));let e=f.event(true,0);let mut paper=Engine::new(&f.policy).unwrap();assert!(paper.advance(&e).is_err());f.mode(true,0);assert!(matches!(Engine::from_seed_state(&f.b().engine().report().unwrap()),Err("SEED_PROFITABLE_DEPTH_REQUIRE_REPLAY")));}
#[test]fn disabled_transition_is_chained_and_restart_retains_exact_quote_and_report(){let mut f=F::new(json!({}));f.adopt("YES",1000);f.mode(true,0);let first=f.b().engine().profitable_depth_mode_record().unwrap().clone();f.mode(false,1);let second=f.b().engine().profitable_depth_mode_record().unwrap();assert_eq!(second["previousSha256"],first["sha256"]);assert_eq!(second["revision"],2);f.yes(2);assert!(f.exits().is_empty());let report=f.b().engine().report().unwrap();let head=f.b().durable_head();f.bank.take();let bank=Session::open_live(&f.root.join("bank"),&f.policy,&f.seed).unwrap();assert_eq!(bank.engine().report().unwrap(),report);assert_eq!(bank.durable_head(),head);assert!(!bank.engine().profitable_depth_enabled());}
